import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200);
  assert.equal(total([]), 0);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  assert.equal(total(lines(10, 11)), 105); // 110 * 0.95 = 104.5
});

test('bulk discount starts at 2 lines', () => {
  assert.equal(total(lines(1, 1000)), 1000);
  assert.equal(total(lines(2, 500)), 950);
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 238); // 250 * 0.95 = 237.5
});

test('customer discount is applied once (#12)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
  assert.equal(total([{ price: 500, qty: 2 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (#12)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
  assert.equal(total(lines(2, 5000), 0.1), 8550);
});

test('bulk threshold can be set by the caller', () => {
  assert.equal(total(lines(9, 1000), 0, 10), 9000);
  assert.equal(total(lines(10, 1000), 0, 10), 9500);
  assert.equal(total(lines(10, 1000), 0.1, 10), 8550);
});
EOF
